(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const s = window.__toolboxStore;
  const out = {};

  // 文件由 --file-input 塞进「打开作品」
  for (let i = 0; i < 40; i++) {
    await sleep(500);
    if (document.querySelector('.pj-title') || document.querySelector('.tb-error')) break;
  }
  out.opened = document.querySelector('.pj-title')?.textContent || null;
  out.diffBadge = document.querySelector('.pj-diff')?.textContent || null;

  // ① 程序代码：中文注释有没有活着到这边
  out.tabs = [...document.querySelectorAll('.pc-tab')].map((b) => b.textContent.trim());
  out.groups = [...document.querySelectorAll('.pc-group-title')].map((e) => e.textContent);
  out.codeName = document.querySelector('.pc-item-name')?.textContent || null;
  out.codeMeta = document.querySelector('.pc-item-meta')?.textContent || null;
  const shown = document.querySelector('.pc-code')?.textContent || '';
  out.chineseOK = shown.includes('三个 LED 轮流亮') && shown.includes('延时半秒');
  out.firstLine = shown.split('\n')[0] || null;

  const projects = await s.listProjects();
  const p = projects.find((x) => x.name.includes('Keil'));
  const bundle = await s.getProject(p.id);
  out.stored = {
    difficulty: bundle.project.difficulty,
    code: bundle.codeFiles.map((c) => ({ n: c.name, g: c.group, e: c.encoding, ok: c.content.includes('三个 LED 轮流亮') })),
    pins: bundle.pinRows.length,
    debugs: bundle.debugNotes.length,
    codeNote: (bundle.project.codeNote || '').slice(0, 16),
  };
  return JSON.stringify(out);
})()
